        name: product.name,
        qty,
        unitPrice: product.unitPrice,
        vatRate: product.vatRate,
        discountPercent: finalDiscountPercent,
      },
    ];
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Check if sku exists
  const lineExists = invoice.lines.some((line) => line.sku === sku);
  if (!lineExists) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if it's the last line
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and marking it as issued.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {string[]} existingNumbers - Array of invoice numbers already used
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check status is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Calculate the due date based on payment terms and issue date.
 * @param {string} issueDate - Date in YYYY-MM-DD format
 * @param {string} terms - 'NET14', 'NET30' (default), or 'EOM'
 * @returns {string} - Due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  switch (terms) {
    case 'NET14':
      return addDays(issueDate, 14);
    case 'NET30':
      return addDays(issueDate, 30);
    case 'EOM':
      return lastDayOfMonth(issueDate);
    default:
      return null;
  }
}

/**
 * Create an invoice from customer, date, and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} param
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  // Validate date
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate terms
  if (terms !== 'NET14' && terms !== 'NET30' && terms !== 'EOM') {
    return fail('TERMS_INVALID');
  }

  // Calculate due date
  const dueDate = calculateDueDate(issueDate, terms);

  // Validate lines array
  if (!lines || lines.length === 0) return fail('NO_LINES');

  // Validate each line and build invoice lines
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate discountPercent if provided
    if ('discountPercent' in line && !isValidDiscount(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }
    // Use provided discountPercent or fall back to customer's tier discount
    const discountPercent = 'discountPercent' in line ? line.discountPercent : TIER_DISCOUNTS[customer.tier];

    // Get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  const invoice = {
    customerId: normalizedCustomerId,
    customerName: customer.name,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
    terms,
    dueDate,
  };

  return ok(invoice);
}

