  const totals = invoiceTotals(invoice);
  const lineTotal = 10 * 1000; // 10000
  const discount = lineTotal * 12.5 / 100; // 1250
  const amountAfterDiscount = lineTotal - discount; // 8750
  const vat = amountAfterDiscount * 21 / 100; // 1837.5 -> 1838

  assert.deepEqual(totals, {
