import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';
import { normalizeId } from '../src/customers.js';

test('createInvoice builds an invoice with customer, date, and line items', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.customerName, 'Northwind Studio');
  assert.equal(result.value.issueDate, '2024-01-15');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);

  assert.deepEqual(result.value.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 5,
    unitPrice: 8500,
    vatRate: 21,
    discountPercent: 5,
  });

  assert.deepEqual(result.value.lines[1], {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 3,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 5,
  });
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-01-15',
