      { sku: 'DEV-HOUR', qty: 3, unitPrice: 9500, name: 'Dev', vatRate: 21, discountPercent: 20 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: 42500, discount 4250, after 38250, VAT 8032.5 -> 8032 (rounded)
  // Line 2: 28500, discount 5700, after 22800, VAT 4788
  // Total VAT: 12820
  assert.deepEqual(totals, {
