test('invoiceTotals sums line totals and includes discount and VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 5, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 3, unitPrice: 9500, name: 'Development (hour)', vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // subtotal: 42500 + 28500 = 71000
  // VAT: (42500 + 28500) * 21 / 100 = 14910
  assert.deepEqual(totals, {
    subtotal: 71000,
    discount: 0,
    vat: 14910,
    voucher: 0,
    total: 71000 + 14910,
