      { sku: 'DEV-HOUR', qty: 8 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // C-001 is gold tier with 5% discount
  const subtotal = 10 * 8500 + 8 * 9500; // 161000
  const discount = subtotal * 5 / 100; // 8050
  // VAT is on amount after discount: (161000 - 8050) * 21 / 100 = 32099.5 -> 32100 (rounded)
  const amountAfterDiscount = subtotal - discount; // 152950
  const vat = amountAfterDiscount * 21 / 100; // 32119.5 -> 32120 (rounded to even)
  assert.deepEqual(totals, {
    subtotal,
    discount,
    vat: 32120,
    voucher: 0,
    total: subtotal - discount + 32120,
  });
});

