test('invoiceTotals with voucher larger than total clamps to 0', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invoice = createResult.value;
  const totals = invoiceTotals(invoice);
  const voucherResult = applyVoucher(invoice, { code: 'BIGSALE', amount: totals.total + 10000 });
  const totalsWithVoucher = invoiceTotals(voucherResult.value);

  assert.equal(totalsWithVoucher.total, 0);
});

test('applyVoucher does not mutate the input invoice', () => {
  const createResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const invoice = createResult.value;
  assert.equal(invoice.voucher, undefined);

  const voucherResult = applyVoucher(invoice, { code: 'SUMMER20', amount: 5000 });

  assert.equal(invoice.voucher, undefined);
  assert.deepEqual(voucherResult.value.voucher, { code: 'SUMMER20', amount: 5000 });
  assert.notEqual(voucherResult.value, invoice);
});

test('invoiceTotals with discount and voucher', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', qty: 5, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 10 },
    ],
    voucher: { code: 'SUMMER20', amount: 2000 },
  };

  const totals = invoiceTotals(invoice);
  const lineTotal = 5 * 8500; // 42500
  const discount = lineTotal * 10 / 100; // 4250
  const amountAfterDiscount = lineTotal - discount; // 38250
  const vat = amountAfterDiscount * 21 / 100; // 8032.5 -> 8032 (rounded)

  assert.deepEqual(totals, {
    subtotal: lineTotal,
    discount,
    vat: 8032,
    voucher: 2000,
    total: lineTotal - discount + 8032 - 2000,
  });
});
